import type { SVGProps } from 'react'

// Icons exported from the Luma Figma file (Phosphor set), recolored to currentColor.

type IconProps = SVGProps<SVGSVGElement> & { size?: number }

function Icon({ size = 24, viewBox = '0 0 24 24', children, ...rest }: IconProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox={viewBox}
      fill="none"
      stroke="currentColor"
      strokeWidth={1.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      {...rest}
    >
      {children}
    </svg>
  )
}

export function ArrowLeftIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M20.25 12H3.75" />
      <path d="M10.5 5.25L3.75 12L10.5 18.75" />
    </Icon>
  )
}

export function CaretIcon({ direction = 'left', ...props }: IconProps & { direction?: 'left' | 'right' }) {
  return (
    <Icon size={32} viewBox="0 0 32 32" {...props}>
      <path d={direction === 'left' ? 'M20 26L10 16L20 6' : 'M12 6L22 16L12 26'} />
    </Icon>
  )
}

